// ---- Workflow configuration: edit these values for your environment ----
const CONFIG = {
 api_base_url: "http://host.docker.internal:8000",   // Sentient AI matching service (sentient_api.py)
  // 0.50 chosen from the M2 holdout: 91/108 full notes released, 92% of those correct.
  // A wrong release costs a misrouted draft that staff only catch at approval.
  confidence_threshold: 0.50,               // below this, the case goes to staff review
  short_intake_review_chars: 200,           // M2 commitment: intake shorter than this goes to staff
  abdominal_pelvic_group: ["Gastroenterology", "Nephrology", "Urology", "Obstetrics / Gynecology"],
  staff_email: "referrals-staff@example.com",
  clinic_name: "Sentient AI Referral Clinic",
  summary_model: "claude-opus-5-5",          // Claude model for the staff summary (claude-haiku-5-5 is cheaper)
  timezone: "America/Chicago",
  default_appointment_time: "09:00",
  appointment_minutes: 30,
  calendar_id: "primary",                  // staff "Draft Referrals" calendar ID
};

const envelope = $input.first().json;
const input = envelope.body ?? envelope;
const str = (v) => (typeof v === "string" ? v.trim() : "");

const caseId = str(input.case_id);
const clinicalText = str(input.clinical_text ?? input.clinical_notes ?? input.text);
const patientEmail = str(input.patient_email).toLowerCase();
const preferredDate = str(input.preferred_date);

const missingFields = [];
const invalidFields = [];
const aliases = ['clinical_text', 'clinical_notes', 'text'].filter(k => input[k] !== undefined);
if (aliases.some(k => str(input[k]) !== clinicalText)) invalidFields.push('conflicting clinical text fields');
if (input.screening_complete !== undefined && typeof input.screening_complete !== 'boolean') invalidFields.push('screening_complete (use a JSON boolean)');
if (!caseId) missingFields.push("case_id");
if (!clinicalText) missingFields.push("clinical_text");
if (!patientEmail) missingFields.push("patient_email");
else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(patientEmail)) invalidFields.push("patient_email");
if (preferredDate && !/^\d{4}-\d{2}-\d{2}$/.test(preferredDate)) invalidFields.push("preferred_date (use YYYY-MM-DD)");

const valid = missingFields.length === 0 && invalidFields.length === 0;

return [{
  json: {
    case_id: caseId,
    // De-identified text: the only field sent to the matcher and the LLM.
    clinical_text: clinicalText,
    // Contact details: used only for the patient email, never sent to the matcher or LLM.
    patient_email: patientEmail,
    patient_first_name: str(input.patient_first_name),
    preferred_date: preferredDate || null,
    screening_complete: input.screening_complete === true,
    validation_status: valid ? "VALID" : "INVALID",
    missing_fields: missingFields,
    invalid_fields: invalidFields,
    received_at: new Date().toISOString(),
    config: CONFIG,
  },
}];

const intake = $('Validate Intake').first().json;
// Invalid intake never reaches the model service, staff email or queue.
return [{ json: { http_status: 400, body: {
  case_id: intake.case_id || null,
  validation_status: 'INVALID',
  missing_fields: intake.missing_fields,
  invalid_fields: intake.invalid_fields,
  message: 'Intake rejected. Provide the missing or invalid fields and resubmit.',
} } }];

const intake = $('Validate Intake').first().json;
const gate = $input.first().json;

const response = {
  case_id: intake.case_id,
  safety_status: "EMERGENCY_ESCALATED",
  priority: "HIGH",
  booking_allowed: false,
  specialty: null,
  draft_booking: null,
  staff_approval_required: true,
  guidance: gate.guidance,
};

const queue_row = {
  case_id: intake.case_id,
  received_at: intake.received_at,
  route: "EMERGENCY_ESCALATED",
  priority: "EMERGENCY",
  reason: "Deterministic safety gate detected emergency indicators",
  specialty_suggestion: "", confidence: "", ci95_low: "", ci95_high: "",
  clinical_summary: "", clarification_questions: "",
  status: "OPEN", assigned_to: "", reviewer_decision: "", reviewed_at: "",
};

return [{
  json: {
    response,
    queue_row,
    staff_subject: `URGENT: emergency indicators in case ${intake.case_id}`,
    staff_message:
      `Case ${intake.case_id} matched emergency indicators in the deterministic safety gate.\n\n` +
      `No specialty matching or booking was run. The submitter was shown emergency guidance.\n` +
      `Follow up with the patient directly.\n\nReceived: ${intake.received_at}`,
  },
}];

const intake = $('Validate Intake').first().json;
const m = $input.first().json;
const s = $('Validate Staff Summary').first().json.output ?? {};
const threshold = intake.config.confidence_threshold;

const SUPPORTED = [
  "Cardiovascular / Pulmonary", "Orthopedic", "Gastroenterology", "Neurology",
  "Obstetrics / Gynecology", "Urology", "ENT - Otolaryngology", "Nephrology",
  "Dermatology", "Ophthalmology",
];

// Same rule as cardio_pulmonary_subroute() in the Milestone 2 notebook.
function cardioPulmonarySubroute(text) {
  const cardiac = /\b(cardiac|coronary|arrhythmia|heart failure|palpitations)\b/i.test(text);
  const pulmonary = /\b(pulmonary|asthma|COPD|wheez(?:e|ing)|lung)\b/i.test(text);
  if (cardiac === pulmonary) return null;
  return cardiac ? "Cardiology" : "Pulmonology";
}

// M2 commitment: the GI / Nephrology / Urology / OB-GYN boundary goes to staff.
// Triggered when the top two candidates both fall inside that group.
function abdominalPelvicBoundary(match) {
  const group = intake.config.abdominal_pelvic_group;
  const top = (match.top_candidates ?? []).slice(0, 2).map(c => c.specialty);
  return top.length === 2 && top.every(s => group.includes(s)) ? top.join(" vs ") : null;
}

const missing = Array.isArray(s.missing_information) ? s.missing_information : [];
let reviewReason = null;
let proposed = null;

const gate = $('Run Safety Gate').first().json;
if (intake.validation_status !== 'VALID' || intake.screening_complete !== true || gate.safety_status !== 'NONEMERGENCY_ELIGIBLE' || (m.safety_status !== undefined && m.safety_status !== 'NONEMERGENCY_ELIGIBLE')) {
  reviewReason = 'Intake or safety screening does not permit booking.';
} else if (!Number.isFinite(threshold) || threshold < 0 || threshold > 1) {
  reviewReason = 'Invalid confidence threshold configuration.';
} else if (typeof s.summary !== 'string' || !s.summary.trim() || !Array.isArray(s.missing_information)) {
  reviewReason = 'Summary output is missing or malformed.';
} else if (m.match_status !== "MATCHED") {
  reviewReason = m.reason || "The matcher did not return a specialty.";
} else if (!SUPPORTED.includes(m.specialty)) {
  reviewReason = `Unsupported specialty returned: ${m.specialty}`;
} else if (!Number.isFinite(m.confidence) || m.confidence < 0 || m.confidence > 1 || m.confidence < threshold) {
  reviewReason = `Low confidence: ${m.confidence} is below the ${threshold} threshold.`;
} else if (intake.clinical_text.length < intake.config.short_intake_review_chars) {
  reviewReason = `Short intake (${intake.clinical_text.length} characters, under ${intake.config.short_intake_review_chars}): staff must confirm the specialty.`;
} else if (abdominalPelvicBoundary(m)) {
  reviewReason = `Abdominal-pelvic boundary: top candidates ${abdominalPelvicBoundary(m)} are both in the GI / Nephrology / Urology / OB-GYN group identified in the M2 error analysis.`;
} else if (m.specialty === "Cardiovascular / Pulmonary") {
  proposed = cardioPulmonarySubroute(intake.clinical_text);
  reviewReason = "Combined Cardiovascular / Pulmonary label: staff must confirm Cardiology or Pulmonology before any draft.";
} else if (missing.length) {
  reviewReason = "The intake is missing information needed for a referral.";
}

return [{
  json: {
    ...m,
    booking_allowed: reviewReason === null,
    review_reason: reviewReason,
    proposed_scheduling_specialty: proposed,
    confidence_threshold: threshold,
    intake_summary: s.summary ?? null,
    missing_information: missing,
  },
}];

const intake = $('Validate Intake').first().json;
const match = $('Apply Booking Policy').first().json;
const summary = match.intake_summary ?? null;
const cfg = intake.config;

// Earliest slot: next business day. Honor the preferred date if it is a weekday on or after that.
const now = DateTime.now().setZone(cfg.timezone);
let earliest = now.plus({ days: 1 }).startOf("day");
while (earliest.weekday > 5) earliest = earliest.plus({ days: 1 });

let slot = intake.preferred_date
  ? DateTime.fromISO(intake.preferred_date, { zone: cfg.timezone })
  : null;
const preferredHonored = Boolean(slot && slot.isValid && slot >= earliest && slot.weekday <= 5);
if (!preferredHonored) slot = earliest;

const [hour, minute] = cfg.default_appointment_time.split(":").map(Number);
slot = slot.set({ hour, minute, second: 0, millisecond: 0 });

const draft = {
  draft_id: `DRAFT-${intake.case_id}-${now.toFormat("yyyyLLddHHmmss")}`,
  status: "DRAFT_PENDING_STAFF_APPROVAL",
  specialty: match.specialty,
  proposed_start: slot.toISO(),
  proposed_end: slot.plus({ minutes: cfg.appointment_minutes }).toISO(),
  duration_minutes: cfg.appointment_minutes,
  timezone: cfg.timezone,
  preferred_date: intake.preferred_date,
  preferred_date_honored: preferredHonored,
  created_at: now.toISO(),
};

const response = {
  case_id: intake.case_id,
  safety_status: "NONEMERGENCY_ELIGIBLE",
  booking_allowed: true,
  specialty: match.specialty,
  confidence: match.confidence,
  confidence_interval: match.confidence_interval ?? null,
  model_run_id: match.model_run_id,
  staff_approval_required: true,
  draft_booking: draft,
  intake_summary: summary,
};

const ci = match.confidence_interval;
const calendarDescription = [
  "DRAFT created by Sentient AI. Requires staff approval before it is confirmed.",
  "",
  `Case: ${intake.case_id}`,
  `Specialty: ${match.specialty}`,
  `Confidence (MLP 64, ${match.model_run_id}): ${match.confidence} (threshold ${match.confidence_threshold})`,
  ci ? `Validation accuracy in band ${ci.band}: ${ci.validation_accuracy}, 95% CI ${ci.ci95_low}-${ci.ci95_high} (n=${ci.n_validation_cases})` : "",
  "",
  "Intake summary (de-identified):",
  summary ?? "(not available)",
].join("\n");

return [{
  json: {
    response,
    calendar_title: `[DRAFT - needs staff approval] ${match.specialty} referral - case ${intake.case_id}`,
    calendar_description: calendarDescription,
  },
}];

const draft = $('Draft Appointment').first().json;
const intake = $('Validate Intake').first().json;
const ev = $input.first().json;
// The patient is NOT emailed here. The notice is held until a staff member sets
// reviewer_decision = APPROVED in the Review Queue sheet; the separate
// "Sentient AI - Staff Approval Notifier" workflow then sends it.
const r = { ...draft.response, patient_email_sent: false, patient_notice: "HELD_FOR_STAFF_APPROVAL" };
r.draft_booking = { ...r.draft_booking, calendar_event_id: ev.id ?? null, calendar_link: ev.htmlLink ?? null };
const d = r.draft_booking;
const ci = r.confidence_interval;

const staffMessage =
`Draft appointment ${d.draft_id} needs staff approval. The patient has NOT been contacted.

Case: ${r.case_id}
Specialty: ${r.specialty} (confidence ${r.confidence}, model ${r.model_run_id})
Proposed start: ${d.proposed_start} (${d.timezone})
Calendar draft: ${d.calendar_link ?? "(link unavailable)"}
Preferred date honored: ${d.preferred_date_honored ? "yes" : "no"}

To approve: set reviewer_decision to APPROVED on this case's row in the Review Queue sheet.
The patient notice is sent only after that. To reject, set it to REJECTED and contact the patient directly.

Intake summary (de-identified):
${r.intake_summary ?? "(not available)"}`;

const queue_row = {
  case_id: r.case_id,
  received_at: intake.received_at,
  route: "DRAFT_PENDING_APPROVAL",
  priority: "ROUTINE",
  reason: "Eligible, confident match; draft created and held for staff approval",
  specialty_suggestion: r.specialty,
  confidence: r.confidence,
  ci95_low: ci?.ci95_low ?? "",
  ci95_high: ci?.ci95_high ?? "",
  clinical_summary: r.intake_summary ?? "",
  clarification_questions: "",
  status: "PENDING_APPROVAL",
  proposed_start: d.proposed_start,
  calendar_event_id: d.calendar_event_id ?? "",
  calendar_link: d.calendar_link ?? "",
  patient_email: intake.patient_email,
  patient_first_name: intake.patient_first_name,
};

return [{ json: { response: r, staff_subject: `Approve draft appointment: case ${r.case_id}`, staff_message: staffMessage, queue_row } }];

// Every non-emergency path that cannot be booked automatically ends here.
// It never substitutes a default specialty.
const intake = $('Validate Intake').first().json;
const j = $input.first().json;
const tryNode = (name) => { try { return $(name).first().json; } catch (e) { return null; } };

let reason;
let questions = [];
if (j.error) {
  const msg = typeof j.error === "string" ? j.error : (j.error.message || "");
  reason = `A workflow step failed, so the case was not routed automatically. ${msg}`.trim();
} else if (j.review_reason) {
  reason = j.review_reason;
  questions = j.missing_information ?? [];
} else if (j.safety_status === "REVIEW_REQUIRED") {
  reason = j.guidance || "Screening requires review.";
} else {
  reason = "Unrecognized result; routed to staff review.";
}

// Pull the Claude summary and model output if those steps ran.
const summary = tryNode('Validate Staff Summary')?.output?.summary ?? null;
const policy = j.specialty ? j : tryNode('Apply Booking Policy');
const suggestion = policy && policy.specialty
  ? { specialty: policy.specialty, confidence: policy.confidence ?? null,
      confidence_interval: policy.confidence_interval ?? null,
      proposed_scheduling_specialty: policy.proposed_scheduling_specialty ?? null,
      top_candidates: policy.top_candidates ?? [] }
  : null;

const response = {
  case_id: intake.case_id,
  safety_status: "REVIEW_REQUIRED",
  booking_allowed: false,
  specialty: null,
  draft_booking: null,
  staff_approval_required: true,
  review_reason: reason,
  clarification_questions: questions,
  guidance: "This referral has been sent to clinical staff for manual review.",
};

let staffMessage = `Case ${intake.case_id} needs manual review.\n\nReason: ${reason}\n`;
if (questions.length) staffMessage += `\nClarification needed:\n- ${questions.join("\n- ")}\n`;
if (suggestion) {
  staffMessage += `\nModel suggestion (not booked): ${suggestion.specialty}` +
    (suggestion.confidence !== null ? ` (confidence ${suggestion.confidence})` : "") +
    (suggestion.proposed_scheduling_specialty ? `; keyword sub-route: ${suggestion.proposed_scheduling_specialty}` : "") + "\n";
}
if (summary) staffMessage += `\nIntake summary (de-identified):\n${summary}\n`;
staffMessage += `\nReceived: ${intake.received_at}`;

const ci = suggestion?.confidence_interval;
const queue_row = {
  case_id: intake.case_id,
  received_at: intake.received_at,
  route: "CLINICAL_REVIEW",
  priority: j.error ? "HIGH" : (j.safety_status === "REVIEW_REQUIRED" ? "HIGH" : "ROUTINE"),
  reason,
  specialty_suggestion: suggestion?.specialty ?? "",
  confidence: suggestion?.confidence ?? "",
  ci95_low: ci?.ci95_low ?? "",
  ci95_high: ci?.ci95_high ?? "",
  clinical_summary: summary ?? "",
  clarification_questions: questions.join("; "),
  status: "OPEN",
  assigned_to: "",
  reviewer_decision: "",
  reviewed_at: "",
};

return [{ json: { response, staff_subject: `Review needed: case ${intake.case_id}`, staff_message: staffMessage, queue_row } }];

const tryNode = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
// Exactly one of these ran in this execution.
const result = tryNode('Build Booking Result') ?? tryNode('Build Review Result') ?? tryNode('Build Emergency Result');
// One row shape for every route (emergency, review, draft). Blank columns stay blank for staff.
const COLS = ["case_id", "received_at", "route", "priority", "reason", "specialty_suggestion", "confidence", "ci95_low", "ci95_high", "clinical_summary", "clarification_questions", "status", "proposed_start", "calendar_event_id", "calendar_link", "patient_email", "patient_first_name", "assigned_to", "reviewer_decision", "reviewed_at", "patient_notified_at"];
const q = result?.queue_row ?? {};
const row = Object.fromEntries(COLS.map(c => [c, q[c] ?? '']));
return [{ json: row }];

const raw = $input.first().json;
// Raw Anthropic Messages API response: take the text blocks, then parse the JSON object inside.
let s = null;
if (Array.isArray(raw.content)) {
  const text = raw.content.filter(b => b.type === 'text').map(b => b.text).join('').trim();
  const start = text.indexOf('{'), end = text.lastIndexOf('}');
  if (start !== -1 && end > start) { try { s = JSON.parse(text.slice(start, end + 1)); } catch (_) { s = null; } }
}
const valid = s && typeof s.summary === 'string' && s.summary.trim().length > 0
  && Array.isArray(s.missing_information) && s.missing_information.every(q => typeof q === 'string' && q.trim().length > 0);
const questions = valid ? s.missing_information : [];
return [{json: {
  output: valid ? { summary: s.summary, missing_information: questions } : null,
  summary_ready: Boolean(valid && questions.length === 0),
  missing_information: questions,
  stop_reason: raw.stop_reason ?? null,
  review_reason: !valid ? 'Summary output is missing or malformed.' : questions.length ? 'Clarification is required before specialty matching.' : null
}}];

const tryNode = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
// Exactly one of these ran in this execution.
const result = tryNode('Build Booking Result') ?? tryNode('Build Review Result') ?? tryNode('Build Emergency Result');
const staff = tryNode('Notify Clinical Staff') ?? {};
const queue = $input.first().json;
const queueFailed = queue.queue_write_status === 'FAILED';
const staffFailed = Boolean(staff.error);

const body = {
  ...result.response,
  staff_email_sent: !staffFailed,
  queue_write_status: queueFailed ? 'FAILED' : 'WRITTEN',
  manual_action_required: queueFailed || staffFailed,
};
return [{ json: { http_status: 200, body } }];

